/* Exercise the production SMC input queues, dispatch, encoder routing and clip
 * editor entry with menu/help covering the stage or its X0X fallback page. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "x0x_cold.h"
#include "app/smc_protocol.h"
#include "smc_fx_harness_stubs.h"
#define CK_FN __attribute__((unused))
#include "app/smk_clip_keys.h"

enum { O_NONE, O_LIST, O_ASK, R_NONE, R_HDR, R_ACT, R_ENG, EN_K1, NE,
       B_HOME, NKIT = 2, PROJ_BT_SMC_CENTRAL = 16, PROJ_BT_SMC_USER = 32 };
typedef struct { uint8_t kind; } pref_t;
static struct { struct { uint8_t bt; } set; } proj;
static struct {
    uint8_t overlay, help;
    uint32_t act_t;
    uint32_t enc_t[NE];
    uint8_t enc_run[NE];
} ui;
static struct { uint8_t pg; } ck;
static uint8_t clip_grid_mode, fields[CK_NE];
static unsigned dirty, notices, fallback_turns;
static int page_value;
static uint32_t ck_get(uint32_t f) { return fields[f]; }
static void ck_set(uint32_t f, uint32_t v) { fields[f] = (uint8_t)v; }
static void mark_dirty(void) { dirty++; }
static void ui_say(const char *a, const char *b) { (void)a; (void)b; notices++; }
static void smc_ui_clip_show(int n, const char *a, const char *b)
{ (void)n; (void)a; (void)b; notices++; }
#define smc_ui_cancel() ((void)0) /* This fixture observes routing, not presentation. */
static char *put_s(char *d, const char *s) { while ((*d++ = *s++)) {} return d - 1; }
static const char *ck_val_txt(uint32_t f, uint32_t v, char *s)
{
    (void)f;
    sprintf(s, "%u", (unsigned)v);
    return s;
}
#include "clip_turn.inc"

static uint8_t perf_testing(void) { return 0; }
static int ui_project_busy(void) { return 0; }
static void button_tap(int button) { (void)button; }
static void engine_smc_solo(uint8_t solo) { (void)solo; }
static void smc_button(uint8_t note, int mmc) { (void)note; (void)mmc; }
static void smc_release(uint8_t note) { (void)note; }
static void smc_fader(int n, uint8_t value) { (void)n; (void)value; }
static pref_t smc_page_target(int n) { (void)n; return (pref_t){R_NONE}; }
static int smc_fader_of(pref_t r) { (void)r; return 0; }
static pref_t smc_knob_target(int n) { (void)n; return (pref_t){R_ENG}; }
static void turn_ref(pref_t r, int delta, int enc)
{
    (void)r; (void)enc;
    fallback_turns++;
    page_value += delta;
}
static uint32_t plat_ms(void) { return 1234u; }
static void smc_show(int n, int knob, pref_t r) { (void)n; (void)knob; (void)r; notices++; }
#include "smc_input.inc"
#include "smc_turn.inc"

static int fails, route;
static const char *const ROUTES[] = {"BLE DAW", "BLE USER", "host USER"};
static void check(const char *label, int ok)
{
    printf("%s %s page %u: %s\n", ok ? "PASS" : "FAIL", ROUTES[route], ck.pg & 3u, label);
    fails += !ok;
}
static void turn(int n, uint8_t value)
{
    uint8_t msg[3] = {route == 2 ? 0xBFu : 0xB0u, (uint8_t)(16 + n), value};
    if (route == 2) {
        if (!smc_midi_host(0x0Bu | (uint32_t)msg[0] << 8 | (uint32_t)msg[1] << 16 | (uint32_t)msg[2] << 24))
            check("host accepts the encoder message", 0);
    } else
        smc_ble_midi(msg, sizeof msg);
    smc_poll();
}
static void covered(uint8_t overlay, uint8_t help)
{
    uint8_t before[CK_NE];
    unsigned d = dirty, nt = notices, ft = fallback_turns;
    int pv = page_value;
    uint32_t act = ui.act_t;
    memcpy(before, fields, sizeof before);
    ui.overlay = overlay;
    ui.help = help;
    for (int n = 0; n < 8; n++)
        turn(n, 1);
    if (overlay == O_LIST && !help) {
        check("menu owns encoders without editing covered clip fields",
              !memcmp(before, fields, sizeof before) && dirty == d &&
              fallback_turns == ft + 8 && page_value == pv + 8);
    } else if (help) {
        if (clip_grid_mode && !(ck.pg & 3u)) {
            /* Grid itself still swallows encoders; help must not become a second lock. */
            check("help leaves clip-grid encoders inactive",
                  !memcmp(before, fields, sizeof before) && dirty == d &&
                  fallback_turns == ft && page_value == pv && ui.help == 1);
        } else {
            check("help leaves encoders working under the card",
                  (dirty != d || fallback_turns != ft || page_value != pv ||
                   memcmp(before, fields, sizeof before)) && ui.help == 1);
        }
    } else {
        check("confirmation blocks clip fields and X0X fallback",
              !memcmp(before, fields, sizeof before) && dirty == d && notices == nt &&
              fallback_turns == ft && page_value == pv && ui.act_t == act);
    }
    check("covered encoder events are drained", smc_qr == smc_qw && smc_host_r == smc_host_w);
    memcpy(before, fields, sizeof before);
    d = dirty;
    ft = fallback_turns;
    pv = page_value;
    ui.overlay = O_NONE;
    ui.help = 0;
    smc_poll();
    check("closing the overlay does not replay turns", !memcmp(before, fields, sizeof before) &&
          dirty == d && fallback_turns == ft && page_value == pv);
}
int main(void)
{
    for (route = 0; route < 3; route++) {
        proj.set.bt = PROJ_BT_SMC_CENTRAL | (route ? PROJ_BT_SMC_USER : 0);
        smc_ble_link(1);
        smc_poll();
        clip_grid_mode = 1;
        for (unsigned page = 1; page <= 3; page++) {
            unsigned d = dirty, ft = fallback_turns;
            uint32_t f = CK_PAGE_FIELDS[page - 1][0];
            memset(fields, 0, sizeof fields);
            ck.pg = (uint8_t)page;
            turn(0, 1);
            check("visible stage edits its first field", fields[f] == 1 && dirty == d + 1 && fallback_turns == ft);
            covered(O_LIST, 0);
            covered(O_NONE, 1);
            covered(O_ASK, 0);
            turn(0, 0x41);
            check("visible stage resumes editing", fields[f] == 0 && fallback_turns == ft + 8);
        }
        ck.pg = 0;                    /* clip grid, with the normal X0X page underneath */
        covered(O_LIST, 0);
        covered(O_NONE, 1);
        clip_grid_mode = 0;            /* normal X0X page, with a stale stage selection */
        ck.pg = 1;
        covered(O_LIST, 0);
        covered(O_NONE, 1);
        {
            unsigned ft = fallback_turns;
            int pv = page_value;
            turn(0, 1);
            check("visible X0X fallback still edits", fallback_turns == ft + 1 && page_value == pv + 1);
        }
    }
    printf("smc_clip_visibility: %s (%d failures)\n", fails ? "failed" : "ok", fails);
    return fails != 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* hal/fm1_input.h's quadrature decoder (fm1__frame) on simulated turns: encoder 0, a full
 * quadrature cycle per detent. A turn must count every detent whether the matrix scan sees each
 * state for 4 scans, 2 or 1, or skips every other state (a fast flick); a one-scan glitch at rest
 * must count nothing. (The scan runs every 1.1 ms: one scan a state is ~225 detents a second.) */
#include <stdio.h>
#include <string.h>
#include "fm1_input.h"

static int fails;
static void frame(uint32_t st)                       /* encoder 0: A = col 0 bit 0, B = col 1 bit 0 */
{
    fm1_in.raw[0] = (uint8_t)((st >> 1) & 1u);
    fm1_in.raw[1] = (uint8_t)(st & 1u);
    fm1__frame();
}
static const uint32_t CW[4] = {1, 3, 2, 0};          /* 0 -> 1 -> 3 -> 2 -> 0: one detent clockwise */

static void reset(void)
{
    int i;
    memset((void *)&fm1_in, 0, sizeof fm1_in);
    for (i = 0; i < (int)FM1_NENC; i++)
        fm1_in.enc_prev[i] = fm1_in.enc_last[i] = 0xFF;
    for (i = 0; i < 60; i++)                         /* at rest on state 0: learned as the detent */
        frame(0);
}

/* `det` detents, `per` scans on each state; skip = 1: only every other state is ever scanned */
static int turn(int det, int per, int skip, int dir)
{
    int d, k, p, steps;
    fm1_in.enc_steps[0] = 0;
    for (d = 0; d < det; d++)
        for (k = skip ? 1 : 0; k < 4; k += skip ? 2 : 1)
            for (p = 0; p < per; p++)
                frame(dir > 0 ? CW[k] : CW[(5 - k) & 3] ^ 0);
    for (k = 0; k < 60; k++)
        frame(0);
    steps = fm1_in.enc_steps[0];
    fm1_in.enc_steps[0] = 0;
    return steps;
}

#define CHECK(c, ...) do { if (!(c)) { printf("FAIL " __VA_ARGS__); printf("\n"); fails++; } } while (0)
int main(void)
{
    int per, got;
    static const uint32_t CCW[4] = {2, 3, 1, 0};
    for (per = 4; per >= 1; per /= 2) {
        reset();
        got = turn(10, per, 0, 1);
        CHECK(got == 10, "10 detents clockwise, %d scans a state: %d", per, got);
    }
    /* a flick: it starts like any turn (one detent seen whole), then skips every other state;
     * from a standstill straight into skipping, the direction is unknowable and nothing counts */
    {
        int k, d;
        reset();
        for (k = 0; k < 4; k++)
            frame(CW[k]);
        for (d = 0; d < 9; d++)
            for (k = 1; k < 4; k += 2)
                frame(CW[k]);
        for (k = 0; k < 60; k++)
            frame(0);
        got = fm1_in.enc_steps[0];
        CHECK(got == 10, "a flick (1 detent whole, then 9 with every other state skipped): %d", got);
    }
    /* counter-clockwise, one scan a state */
    {
        int d, k;
        reset();
        for (d = 0; d < 10; d++)
            for (k = 0; k < 4; k++)
                frame(CCW[k]);
        for (k = 0; k < 60; k++)
            frame(0);
        got = fm1_in.enc_steps[0];
        CHECK(got == -10, "10 detents counter-clockwise, one scan a state: %d", got);
    }
    /* a bounce at rest: one scan of state 1, back to 0 */
    reset();
    frame(1);
    frame(0);
    {
        int k;
        for (k = 0; k < 60; k++)
            frame(0);
    }
    CHECK(fm1_in.enc_steps[0] == 0, "a one-scan glitch at rest counted %d", fm1_in.enc_steps[0]);
    /* a slow turn that pauses halfway through a click (state 1, ~40 ms), then finishes it, and five
     * more: six steps. The pause must not become the knob's detent (it did: the next clicks then
     * landed between detents and some were lost) */
    reset();
    {
        int k, p;
        for (p = 0; p < 70; p++)
            frame(1);
        for (k = 1; k < 4; k++)
            for (p = 0; p < 4; p++)
                frame(CW[k]);
        for (p = 0; p < 60; p++)
            frame(0);
        got = fm1_in.enc_steps[0];
        got += turn(5, 4, 0, 1);
    }
    CHECK(got == 6, "a pause halfway through a click, then 5 more: %d (6)", got);
    /* a pause halfway through a click on the complement of the detent (state 3, a full cycle per
     * click): it must not become a second detent, or every click after it counts two */
    reset();
    {
        int p;
        got = turn(3, 4, 0, 1);
        for (p = 0; p < 4; p++)
            frame(1);
        for (p = 0; p < 70; p++)
            frame(3);
        for (p = 0; p < 4; p++)
            frame(2);
        for (p = 0; p < 60; p++)
            frame(0);
        got += fm1_in.enc_steps[0];
        fm1_in.enc_steps[0] = 0;
        got += turn(5, 4, 0, 1);
    }
    CHECK(got == 9, "a pause on the complement halfway through a click, then 5 more: %d (9)", got);
    /* a half-cycle encoder (it rests on 0 and on 3: two clicks a cycle), turned slowly: after the
     * first few clicks, one step a click */
    reset();
    {
        int c, p, st = 0;
        static const uint32_t SEQ4[4] = {1, 3, 2, 0};
        for (c = 0; c < 6; c++) {                       /* warm-up: it learns its second rest */
            for (p = 0; p < 4; p++) frame(SEQ4[st]);
            st = (st + 1) & 3;
            for (p = 0; p < 4; p++) frame(SEQ4[st]);
            st = (st + 1) & 3;
            for (p = 0; p < 60; p++) frame(SEQ4[(st + 3) & 3]);
        }
        fm1_in.enc_steps[0] = 0;
        for (c = 0; c < 10; c++) {
            for (p = 0; p < 4; p++) frame(SEQ4[st]);
            st = (st + 1) & 3;
            for (p = 0; p < 4; p++) frame(SEQ4[st]);
            st = (st + 1) & 3;
            for (p = 0; p < 60; p++) frame(SEQ4[(st + 3) & 3]);
        }
        got = fm1_in.enc_steps[0];
    }
    CHECK(got == 10, "a half-cycle encoder, 10 slow clicks after warming up: %d (10)", got);
    printf(fails ? "encoder: %d FAILED\n" : "encoder: ok\n", fails);
    return fails != 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Offline native303 render for Chicago AU scenario battery (C-SND-1).
 * Reads a line-oriented control file from stdin; writes stereo float32 LE to stdout.
 *
 * Built at BASS303_SR=48000 (see run_chicago_au_render.sh) so PCM matches AU refs.
 *
 * Usage: chicago_au_render < control.txt > out.f32
 *
 * Control file (one directive per line, # comments):
 *   frames N          total samples per channel @ scenario sampleRate (48 kHz)
 *   note_on F         sample index for note-on
 *   note_off F        sample index for note-off
 *   midi_note N       0..127
 *   velocity N        1..127
 *   pot I V           bass303 pot index and 0..127 value
 *   fx_type T         Chicago Fx Type 0..11 (Crush/Ring/EQ/Cho/Ens/Phaser/SDly/BPM/Hall/GateRev insert when T matches)
 *   fx_edit1 V        Edit1 0..127 (Crush / Ring / EQ / Cho / Ens / Phaser / SDly / BPM / Hall / GateRev wet)
 *   fx_edit2 V        Edit2 0..127 (wet / depth / feedback / BPM division / Hall decay / Gate hold)
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "../../firmware/src/dsp/bass303.h"
#include "../../firmware/src/app/chicago_fx.h"
#include "../../firmware/src/app/chicago_crush.h"
#include "../../firmware/src/app/chicago_ring.h"
#include "../../firmware/src/app/chicago_eq.h"
#include "../../firmware/src/app/chicago_cho.h"
#include "../../firmware/src/app/chicago_ens.h"
#include "../../firmware/src/app/chicago_phaser.h"
#include "../../firmware/src/app/chicago_sdly.h"
#include "../../firmware/src/app/chicago_bpmdly.h"
#include "../../firmware/src/app/chicago_hall.h"
#include "../../firmware/src/app/chicago_gaterev.h"

static int read_ctl(bass303_t *b, chi_crush_t *crush, chi_ring_t *ring, chi_eq_t *eq, chi_cho_t *cho,
                    chi_ens_t *ens, chi_phaser_t *phaser, chi_sdly_t *sdly, chi_bpmdly_t *bpmdly,
                    chi_hall_t *hall, chi_gaterev_t *grev, int *frames, int *note_on, int *note_off,
                    int *midi, int *vel, uint8_t *fx_type)
{
    char line[256];
    uint8_t e1 = 64, e2 = 64;
    *frames = 48000;
    *note_on = 4800;
    *note_off = 24000;
    *midi = 48;
    *vel = 80;
    *fx_type = CHI_FX_OFF;
    bass303_init(b);
    chi_crush_init(crush);
    chi_ring_init(ring);
    chi_eq_init(eq);
    chi_cho_init(cho);
    chi_ens_init(ens);
    chi_phaser_init(phaser);
    chi_sdly_init(sdly);
    chi_bpmdly_init(bpmdly);
    chi_hall_init(hall);
    chi_gaterev_init(grev);
    while (fgets(line, sizeof line, stdin)) {
        int a, c;
        float f;
        if (line[0] == '#' || line[0] == '\n')
            continue;
        if (sscanf(line, "frames %d", &a) == 1) {
            *frames = a;
            continue;
        }
        if (sscanf(line, "note_on %f", &f) == 1) {
            *note_on = (int)(f + 0.5f);
            continue;
        }
        if (sscanf(line, "note_off %f", &f) == 1) {
            *note_off = (int)(f + 0.5f);
            continue;
        }
        if (sscanf(line, "midi_note %d", &a) == 1) {
            *midi = a;
            continue;
        }
        if (sscanf(line, "velocity %d", &a) == 1) {
            *vel = a;
            continue;
        }
        if (sscanf(line, "pot %d %d", &a, &c) == 2) {
            if (a >= 0 && a < BASS303_NPARAMS)
                bass303_set(b, a, c);
            continue;
        }
        if (sscanf(line, "fx_type %d", &a) == 1) {
            if (a < 0)
                a = 0;
            if (a >= CHI_FX_NTYPES)
                a = CHI_FX_OFF;
            *fx_type = (uint8_t)a;
            continue;
        }
        if (sscanf(line, "fx_edit1 %d", &a) == 1) {
            if (a < 0)
                a = 0;
            if (a > 127)
                a = 127;
            e1 = (uint8_t)a;
            continue;
        }
        if (sscanf(line, "fx_edit2 %d", &a) == 1) {
            if (a < 0)
                a = 0;
            if (a > 127)
                a = 127;
            e2 = (uint8_t)a;
            continue;
        }
        fprintf(stderr, "chicago_au_render: unknown line: %s", line);
        return -1;
    }
    if (chi_fx_is_crush_insert(*fx_type))
        chi_crush_set(crush, e1, e2);
    else if (chi_fx_is_ring_insert(*fx_type))
        chi_ring_set(ring, e1, e2, BASS303_SR);
    else if (chi_fx_is_eq_insert(*fx_type))
        chi_eq_set(eq, e1, e2, BASS303_SR);
    else if (chi_fx_is_cho_insert(*fx_type))
        chi_cho_set(cho, e1, e2, BASS303_SR);
    else if (chi_fx_is_ens_insert(*fx_type))
        chi_ens_set(ens, e1, e2, BASS303_SR);
    else if (chi_fx_is_phaser_insert(*fx_type))
        chi_phaser_set(phaser, e1, e2, BASS303_SR);
    else if (chi_fx_is_sdly_insert(*fx_type))
        chi_sdly_set(sdly, e1, e2, BASS303_SR);
    else if (chi_fx_is_bpmdly_insert(*fx_type))
        chi_bpmdly_set(bpmdly, e1, e2, BASS303_SR);
    else if (chi_fx_is_hall_insert(*fx_type))
        chi_hall_set(hall, e1, e2, BASS303_SR);
    else if (chi_fx_is_gaterev_insert(*fx_type))
        chi_gaterev_set(grev, e1, e2, BASS303_SR);
    return 0;
}

int main(void)
{
    bass303_t b;
    chi_crush_t crush;
    chi_ring_t ring;
    chi_eq_t eq;
    chi_cho_t cho;
    chi_ens_t ens;
    chi_phaser_t phaser;
    chi_sdly_t sdly;
    chi_bpmdly_t bpmdly;
    chi_hall_t hall;
    chi_gaterev_t grev;
    int frames, note_on, note_off, midi, vel, pos, note_down;
    uint8_t fx_type;
    float out[512];

    if (read_ctl(&b, &crush, &ring, &eq, &cho, &ens, &phaser, &sdly, &bpmdly, &hall, &grev, &frames,
                 &note_on, &note_off, &midi, &vel, &fx_type) < 0)
        return 2;
    note_down = 0;
    for (pos = 0; pos < frames; pos++) {
        if (!note_down && pos >= note_on) {
            bass303_note_on_velocity(&b, midi, 0, 0, vel);
            note_down = 1;
        }
        if (note_down && pos >= note_off) {
            bass303_note_off(&b);
            note_down = 0;
        }
        bass303_render(&b, out, 1);
        if (chi_fx_is_crush_insert(fx_type))
            chi_crush_process(&crush, out, 1);
        else if (chi_fx_is_ring_insert(fx_type))
            chi_ring_process(&ring, out, 1);
        else if (chi_fx_is_eq_insert(fx_type))
            chi_eq_process(&eq, out, 1);
        else if (chi_fx_is_cho_insert(fx_type))
            chi_cho_process(&cho, out, 1);
        else if (chi_fx_is_ens_insert(fx_type))
            chi_ens_process(&ens, out, 1);
        else if (chi_fx_is_phaser_insert(fx_type))
            chi_phaser_process(&phaser, out, 1);
        else if (chi_fx_is_sdly_insert(fx_type))
            chi_sdly_process(&sdly, out, 1);
        else if (chi_fx_is_bpmdly_insert(fx_type))
            chi_bpmdly_process(&bpmdly, out, 1);
        else if (chi_fx_is_hall_insert(fx_type))
            chi_hall_process(&hall, out, 1);
        else if (chi_fx_is_gaterev_insert(fx_type))
            chi_gaterev_process(&grev, out, 1);
        {
            float s = out[0];
            if (fwrite(&s, sizeof(float), 1, stdout) != 1)
                return 1;
            if (fwrite(&s, sizeof(float), 1, stdout) != 1)
                return 1;
        }
    }
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* drum808 (the port) against 8W8's own sc808_engine.cpp (the reference, built
 * from its sources in double with libm), sound by sound and pot by pot, then a
 * four-bar 808 demo rendered by the port.
 *   drum808_test <demo.wav>
 * Each case renders 1 s after one trigger and reports the reference's peak and
 * RMS, the largest sample difference and the RMS of the difference relative to
 * the reference RMS (PASS < 1e-3). The reference's own reverb and delay returns
 * are set to zero, so its output is the dry kit times its Volume; the port's
 * send buses are checked against that times the send pot. */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sc808_engine.h"
#include "drum808.h"

#define SRATE 44100
#define LEN SRATE                         /* 1 s per case */
#define TOL 1e-3

static float ref_out[4 * SRATE], port_dry[4 * SRATE], port_rev[4 * SRATE], port_dly[4 * SRATE];
static drum808_t port;
static int n_fail, n_cases;
static double worst_rel;
static char worst_name[96];

typedef struct { const char *name; int ref, track, sw; const char *id; const char *pots[8]; } snd_t;
static const snd_t k_snd[16] = {
    {"BD", SC808_BD, D8_BD, 0, "bd", {"tune", "attack", "decay", "tone", "drive", "level", 0}},
    {"SD", SC808_SD, D8_SD, 0, "sd", {"tune", "decay", "snappy", "drive", "level", "rev", "dly", 0}},
    {"LT", SC808_LT, D8_LT, 0, "lt", {"tune", "decay", "drive", "level", "rev", "dly", 0}},
